}
ForgeChimneyDamperMaker.ironStock=16; ForgeChimneyDamperMaker.bronzeStock=12; ForgeChimneyDamperMaker.woodStock=14; ForgeChimneyDamperMaker.leatherStock=8; ForgeChimneyDamperMaker.silverStock=8; ForgeChimneyDamperMaker.goldStock=6; ForgeChimneyDamperMaker.jewelStock=4; ForgeChimneyDamperMaker.pearlStock=4
ForgeChimneyDamperMaker.productStock = {}; ForgeChimneyDamperMaker.buildings = {}; ForgeChimneyDamperMaker.maker = nil; ForgeChimneyDamperMaker.activeMaking = {}; ForgeChimneyDamperMaker.totalProducts = 0; ForgeChimneyDamperMaker.dayTimer = 0
function ForgeChimneyDamperMaker.init() ForgeChimneyDamperMaker.ironStock=16; ForgeChimneyDamperMaker.bronzeStock=12; ForgeChimneyDamperMaker.woodStock=14; ForgeChimneyDamperMaker.leatherStock=8; ForgeChimneyDamperMaker.silverStock=8; ForgeChimneyDamperMaker.goldStock=6; ForgeChimneyDamperMaker.jewelStock=4; ForgeChimneyDamperMaker.pearlStock=4; ForgeChimneyDamperMaker.productStock={}; ForgeChimneyDamperMaker.buildings={}; ForgeChimneyDamperMaker.maker=nil; ForgeChimneyDamperMaker.activeMaking={}; ForgeChimneyDamperMaker.totalProducts=0; ForgeChimneyDamperMaker.dayTimer=0; print("[ForgeChimneyDamperMaker] Royal Forge Chimney Damper Maker System initialized (6 products, 4 buildings)") end
function ForgeChimneyDamperMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ForgeChimneyDamperMaker.maker={name=n or ("Zaklopnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zaklopnik najet: %s (spretnost: %d)",ForgeChimneyDamperMaker.maker.name,s),"success") end; return true end
function ForgeChimneyDamperMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ForgeChimneyDamperMaker.build(id) local ok,e=ForgeChimneyDamperMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ForgeChimneyDamperMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ForgeChimneyDamperMaker.getQualityBonus() local b=0; for _,bd in ipairs(ForgeChimneyDamperMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ForgeChimneyDamperMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ForgeChimneyDamperMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ForgeChimneyDamperMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ForgeChimneyDamperMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ForgeChimneyDamperMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ForgeChimneyDamperMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ForgeChimneyDamperMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ForgeChimneyDamperMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ForgeChimneyDamperMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ForgeChimneyDamperMaker.buildings==0 then return false,"Potrebna zaklopna delavnica" end; if not ForgeChimneyDamperMaker.maker then return false,"Potreben zaklopnik" end; return true end
function ForgeChimneyDamperMaker.make(pt,qty) qty=qty or 1; local ok,e=ForgeChimneyDamperMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ForgeChimneyDamperMaker.ironStock=ForgeChimneyDamperMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ForgeChimneyDamperMaker.bronzeStock=ForgeChimneyDamperMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ForgeChimneyDamperMaker.woodStock=ForgeChimneyDamperMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ForgeChimneyDamperMaker.leatherStock=ForgeChimneyDamperMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ForgeChimneyDamperMaker.silverStock=ForgeChimneyDamperMaker.silverStock-d.silverCost*qty end; if d.goldCost then ForgeChimneyDamperMaker.goldStock=ForgeChimneyDamperMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ForgeChimneyDamperMaker.jewelStock=ForgeChimneyDamperMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ForgeChimneyDamperMaker.pearlStock=ForgeChimneyDamperMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ForgeChimneyDamperMaker.maker then t=math.max(1,t-math.floor(ForgeChimneyDamperMaker.maker.skill/13)) end; table.insert(ForgeChimneyDamperMaker.activeMaking,{id="forgechimneydamper_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ForgeChimneyDamperMaker.completeMaking(m) local q=1.0+(ForgeChimneyDamperMaker.getQualityBonus()/100); if ForgeChimneyDamperMaker.maker then q=q+(ForgeChimneyDamperMaker.maker.skill/140) end; q=math.min(2.5,q); ForgeChimneyDamperMaker.productStock[m.productType]=(ForgeChimneyDamperMaker.productStock[m.productType] or 0)+m.quantity; ForgeChimneyDamperMaker.totalProducts=ForgeChimneyDamperMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ForgeChimneyDamperMaker.maker then ForgeChimneyDamperMaker.maker.itemsMade=ForgeChimneyDamperMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ForgeChimneyDamperMaker.maker.skill=math.min(100,ForgeChimneyDamperMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zaklopnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"forgechimneydamper.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ForgeChimneyDamperMaker.update(dt) if not _G.state then return end; ForgeChimneyDamperMaker.dayTimer=ForgeChimneyDamperMaker.dayTimer+dt; if ForgeChimneyDamperMaker.dayTimer>=30 then ForgeChimneyDamperMaker.dayTimer=0; for i=#ForgeChimneyDamperMaker.activeMaking,1,-1 do local m=ForgeChimneyDamperMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ForgeChimneyDamperMaker.completeMaking(m); table.remove(ForgeChimneyDamperMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ForgeChimneyDamperMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ForgeChimneyDamperMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ForgeChimneyDamperMaker.getStats() return {ironStock=ForgeChimneyDamperMaker.ironStock,bronzeStock=ForgeChimneyDamperMaker.bronzeStock,woodStock=ForgeChimneyDamperMaker.woodStock,leatherStock=ForgeChimneyDamperMaker.leatherStock,silverStock=ForgeChimneyDamperMaker.silverStock,goldStock=ForgeChimneyDamperMaker.goldStock,jewelStock=ForgeChimneyDamperMaker.jewelStock,pearlStock=ForgeChimneyDamperMaker.pearlStock,productStock=ForgeChimneyDamperMaker.productStock,numBuildings=#ForgeChimneyDamperMaker.buildings,hasMaker=ForgeChimneyDamperMaker.maker~=nil,makerName=ForgeChimneyDamperMaker.maker and ForgeChimneyDamperMaker.maker.name or "—",makerSkill=ForgeChimneyDamperMaker.maker and ForgeChimneyDamperMaker.maker.skill or 0,activeMaking=#ForgeChimneyDamperMaker.activeMaking,totalProducts=ForgeChimneyDamperMaker.totalProducts} end
